CREATE OR REPLACE FUNCTION public.fn_event_team_invitation_notifications() RETURNS TRIGGER SECURITY DEFINER SET search_path = public AS  DECLARE v_event_id UUID; BEGIN IF TG_OP = 'INSERT' AND NEW.status = 'PENDING' THEN SELECT event_id INTO v_event_id FROM public.event_team_registrations WHERE id = NEW.registration_id; INSERT INTO public.notifications (user_id, type, payload) VALUES (NEW.invited_user_id, 'PLAYER_INVITED', jsonb_build_object('registration_id', NEW.registration_id, 'invited_by', NEW.invited_by, 'event_id', v_event_id, 'invitation_id', NEW.id)); ELSIF TG_OP = 'UPDATE' AND OLD.status = 'PENDING' AND NEW.status = 'ACCEPTED' THEN DECLARE v_captain_id UUID; BEGIN SELECT captain_id, event_id INTO v_captain_id, v_event_id FROM public.event_team_registrations WHERE id = NEW.registration_id; IF v_captain_id IS NOT NULL THEN INSERT INTO public.notifications (user_id, type, payload) VALUES (v_captain_id, 'PLAYER_ACCEPTED', jsonb_build_object('registration_id', NEW.registration_id, 'user_id', NEW.invited_user_id, 'event_id', v_event_id, 'invitation_id', NEW.id)); END IF; END; END IF; RETURN NEW; END;  LANGUAGE plpgsql;  
